# 1G code bundle (2026-10-12). 2-cover descent on C3_p: Y^2=Q1Q2Q3Q4 (t=u/v).
# Files concatenated: locimg.py (local image), sel2.py (Selmer set), killpair (pair curves), rkill.py (R-curves), scan.py (rank scan).
# Requires: python3, numpy, cypari2 (PARI/GP 2.17.2). Usage: python3 sel2.py 10/1 15/8 ;  python3 rkill.py 11/5
# Soundness notes: local images are supersets (undetermined coordinates expanded to all classes), so the Selmer set is a superset;
# a class delta is killed only when a curve has ellrank upper bound 0 and no torsion point yields a retained t.

######## common: sqclass / factor_primes
import sys, math, itertools, json
from fractions import Fraction as Fr
import numpy as np
import cypari2
pari = cypari2.Pari(); pari.allocatemem(10**9)
def factor_primes(n):
    return [int(p) for p in pari.factor(abs(n))[0]] if abs(n) > 1 else []
def sqclass(x, l):
    # class of nonzero integer x in Q_l^*/squares : (v mod 2, unit class)
    v = 0
    while x % l == 0: x //= l; v += 1
    if l == 2: return (v % 2, x % 8)
    return (v % 2, 1 if pow(x % l, (l - 1) // 2, l) == 1 else -1)

######## locimg.py : superset of {(class Q_i(u,v))_i : (u:v) in P^1(Q_l)}
def local_image(Qs, l, maxdepth=8):
    margin = 3 if l == 2 else 1
    full = [(e, u) for e in (0, 1) for u in ((1, 3, 5, 7) if l == 2 else (1, -1))]
    out = set()
    def classes(x, k, chart):
        res = []; done = True
        for (A, B) in Qs:
            q = (A*x*x + B) if chart == 0 else (A + B*x*x)
            M = l**k; q %= M
            if q == 0: res.append(None); done = False; continue
            w = 0; qq = q
            while qq % l == 0: qq //= l; w += 1
            if w + margin <= k: res.append(sqclass(q, l))
            else: res.append(None); done = False
        return res, done
    def rec(x, k, chart, depth):
        res, done = classes(x, k, chart)
        if done or depth >= maxdepth:
            for combo in itertools.product(*[[c] if c is not None else full for c in res]): out.add(tuple(combo))
            return
        M = l**k
        for j in range(l): rec(x + j*M, k + 1, chart, depth + 1)
    k0 = 3 if l == 2 else 1
    for x in range(l**k0): rec(x, k0, 0, 0)          # (u:v)=(x:1), x in Z_l
    for x in range(0, l**k0, l): rec(x, k0, 1, 0)    # (1:x), x in lZ_l
    return out

######## encoding
def enc(c, l):
    v, u = c
    if l == 2: return v | ({1: 0, 3: 1, 5: 2, 7: 3}[u] << 1)
    return v | ((0 if u == 1 else 1) << 1)

######## killpair : pair curve D*Y^2 = X(alpha X+beta)(gamma X+delta), X=t^2, D=sqf(d_i d_j)
def killpair(Qs, dl, S):
    def sqf(x):
        r = 1
        for l in S:
            c = 0
            while x % l == 0: x //= l; c += 1
            if c % 2: r *= l
        return r
    for i in range(4):
        for j in range(i + 1, 4):
            al, be = Qs[i]; ga, de = Qs[j]; D = sqf(dl[i]*dl[j])
            E = pari.ellinit([0, be*ga*D + al*de*D, 0, be*ga*D*al*de*D, 0])   # y^2=x(x+be*ga*D)(x+al*de*D), X=x/(al*ga*D)
            r = pari.ellrank(E)
            if int(r[1]) != 0: continue
            T = pari.elltors(E); gens = list(T[2]); ords = [int(o) for o in T[1]]; bad = False
            for co in itertools.product(*[range(o) for o in ords]):
                P = pari('[0]')
                for gg, c in zip(gens, co): P = pari.elladd(E, P, pari.ellmul(E, gg, c))
                if P == pari('[0]'): continue
                X = Fr(int(pari.numerator(P[0])), int(pari.denominator(P[0])))/(al*ga*D)
                if X <= 0 or X == 1: continue
                if pari.issquare(X.numerator) and pari.issquare(X.denominator): bad = True
            if not bad: return (i, j, D)
    return None

######## sel2.py : Selmer set of 2-cover classes delta=(d1,d2,d3,d4), d4=sqf(d1d2d3)
def run(a, b):
    e, f = a + b, a - b
    g = math.gcd(e, f)**2
    Qs = [(b*b, a*a), (a*a, b*b), (f*f//g, e*e//g), (e*e//g, f*f//g)]   # (coef u^2, coef v^2)
    R = 1
    for i in range(4):
        for j in range(i + 1, 4):
            A1, B1 = Qs[i]; A2, B2 = Qs[j]; R *= (A1*B2 - A2*B1)
    S = sorted(set([2] + factor_primes(R))); n = len(S); N = 1 << n
    imgs = {}; base = {}
    for l in S:
        w = 3 if l == 2 else 2
        img = local_image(Qs, l)
        imgs[l] = (w, [sum(enc(c, l) << (w*k) for k, c in enumerate(t)) for t in img])
        base[l] = [enc(sqclass(q, l), l) for q in S]
    def classarr(l):
        arr = np.zeros(1, dtype=np.int64)
        for k in range(n): arr = np.concatenate([arr, arr ^ base[l][k]])
        return arr
    C = {l: classarr(l) for l in S}
    ok12 = np.ones((N, N), dtype=bool)
    for l in S:
        w, codes = imgs[l]; m = (1 << w) - 1
        proj = np.zeros((1 << w, 1 << w), dtype=bool)
        for c in codes: proj[c & m, (c >> w) & m] = True
        ok12 &= proj[C[l][:, None], C[l][None, :]]
    allowed = {}
    for l in S:
        w, codes = imgs[l]; al = np.zeros(1 << (4*w), dtype=bool); al[codes] = True; allowed[l] = al
    sel = []
    for i1, i2 in np.argwhere(ok12):
        ok = np.ones(N, dtype=bool)
        for l in S:
            w, _ = imgs[l]
            c1 = C[l][i1]; c2 = C[l][i2]; c3 = C[l]; c4 = c1 ^ c2 ^ c3
            ok &= allowed[l][c1 | (c2 << w) | (c3 << (2*w)) | (c4 << (3*w))]
        for i3 in np.nonzero(ok)[0]:
            ds = []
            for idx in (i1, i2, i3):
                d = 1
                for k in range(n):
                    if (int(idx) >> k) & 1: d *= S[k]
                ds.append(d)
            x = ds[0]*ds[1]*ds[2]; d4 = 1
            for q in S:
                c = 0
                while x % q == 0: x //= q; c += 1
                if c % 2: d4 *= q
            sel.append(tuple(ds) + (d4,))
    return Qs, S, sel

######## rkill.py : R-curves (valid for classes with d1=d2, d3=d4): x=R^2, x-4, x+h^2, x+16/h^2 all squares
def curves(a, b):
    n = a*a - b*b; m = a*b
    return [([0, n*n - 4*m*m, 0, -4*m*m*n*n, 0], m*m),          # E_AB: x(x-4)(x+h^2), X=x*m^2
            ([0, 16*m*m - 4*n*n, 0, -64*m*m*n*n, 0], n*n),      # E_AC: x(x-4)(x+16/h^2), X=x*n^2
            ([0, n**4 + 16*m**4, 0, 16*m**4*n**4, 0], (m*n)**2)] # E_BC: x(x+h^2)(x+16/h^2) (same conductor as E_tau)
def rkill(a, b):
    out = []
    n = a*a - b*b; m = a*b; h2 = Fr(n*n, m*m)
    sq = lambda q: q >= 0 and pari.issquare(q.numerator) and pari.issquare(q.denominator)
    for c, sc in curves(a, b):
        E = pari.ellinit(c); r = pari.ellrank(E)
        if int(r[1]) != 0: out.append(None); continue
        T = pari.elltors(E); gens = list(T[2]); ords = [int(o) for o in T[1]]; bad = []
        for co in itertools.product(*[range(o) for o in ords]):
            P = pari('[0]')
            for g, cc in zip(gens, co): P = pari.elladd(E, P, pari.ellmul(E, g, cc))
            if P == pari('[0]'): continue
            x = Fr(int(pari.numerator(P[0])), int(pari.denominator(P[0])))/sc
            if x <= 0 or x == 4: continue
            if sq(x) and sq(x - 4) and sq(x + h2) and sq(x + 16/h2): bad.append(str(x))
        out.append('KILL' if not bad else ('BAD', bad))
    return out

if __name__ == '__main__':
    for arg in sys.argv[1:]:
        a, b = map(int, arg.split('/'))
        Qs, S, sel = run(a, b)
        kills = [(d, killpair(Qs, d, S)) for d in sel]
        un = [d for d, k in kills if k is None]
        rk = rkill(a, b) if un and all(d[0] == d[1] and d[2] == d[3] for d in un) else None
        excluded = (not un) or (rk is not None and 'KILL' in rk)
        print(json.dumps(dict(p=arg, S=S, nsel=len(sel), sel=sel[:8], unkilled=un[:8], rcurves=rk, excluded=excluded)), flush=True)

# 1I code (2026-10-13): 2-cover descent over K=Q(i) restricted to t in P^1(Q) + "rank 0 over K" kill. Requires 1G_code_bundle (sel2.run, killpair, rkill).
# Files: kchab.setup/curveQ (below), kdesc.py (below), combo.py (below).
#
# Math summary:
#  C3_p: Y^2 = Q1Q2Q3Q4, Q_j = N(l_j), l_j = A_j u + i B_j v, (A,B) = (b,a),(a,b),(f,e),(e,f) (e=a+b, f=a-b).
#  Sign pattern s (s1=+1): l_j^s = A_j u + i s_j B_j v.  Gamma_s(t) = prod_j l_j^s(t).  Gamma_s * conj(Gamma_s) = Y^2 for a point,
#  so the class of Gamma_s in K*/K*^2 is Galois invariant; since H^1(Gal(K/Q), K*^2) = 0 (the quaternion algebra (-1,-1)_Q is non-split),
#  the class is that of a rational d.  l_3^s = al*l_1 + be*l_2^s, l_4^s = al2*l_1 + be2*l_2^s with al,be,al2,be2 in Q, and
#  Gamma_s = (l_2^s)^4 * mu(al mu+be)(al2 mu+be2), mu = l_1/l_2^s  (identity checked exactly on 192 cases).
#  Hence a K-point on E_s^(d): d y^2 = mu(al mu+be)(al2 mu+be2); rank E_s^(d)(K) = rank E_s^(d)(Q) + rank E_s^(-d)(Q).
#  If both are 0, the K-points are K-torsion (PARI elltors over nf); t = i(a - s2 b mu)/(a mu - b) is recovered and tested.
#  The possible (gamma_1..gamma_4) are cut by local images of t in P^1(Q_l) at every l in S (split l: both embeddings; inert: Z_l[i];
#  l=2: Q_2(i), unit classes mod pi^5).  Class maps were checked to be homomorphisms killing squares (3200 random tests, 0 bad).

######## kchab.py (excerpt used)
import math
from fractions import Fraction as Fr
def setup(a, b, s):
    e, f = a + b, a - b
    AB = [(b, a), (a, b), (f, e), (e, f)]
    L = [(A, si * B) for (A, B), si in zip(AB, s)]
    (A1, B1), (A2, B2) = L[0], L[1]
    det = A1 * B2 - A2 * B1
    def co(A3, B3): return Fr(A3 * B2 - A2 * B3, det), Fr(A1 * B3 - A3 * B1, det)
    al, be = co(*L[2]); al2, be2 = co(*L[3])
    return L, (al, be, al2, be2)

def curveQ(c, d):
    al, be, al2, be2 = c
    A = be * al2 * d; B = al * be2 * d; den = 1
    for q in (A, B): den = den * q.denominator // math.gcd(den, q.denominator)
    return [0, int((A + B) * den * den), 0, int(A * B * den**4), 0], Fr(al * al2 * d * den * den)   # x = scale*mu

######## kdesc.py
import sys, itertools, math, json
import numpy as np
import cypari2
pari = cypari2.Pari(); pari.allocatemem(2 * 10**9)
from sel2 import run as selrun
K = pari('nfinit(y^2+1)')

def v_l(x, l):
    if x == 0: return 10**9
    v = 0
    while x % l == 0: x //= l; v += 1
    return v
def leg(x, l): return 0 if pow(x % l, (l - 1) // 2, l) == 1 else 1

# 2-adic: Z[i]/(pi^5), pi = 1+i
def red32(x, y):
    x %= 8; y %= 8
    if y >= 4: x = (x - 4) % 8; y -= 4
    return (x, y)
def gmul(a, b): return (a[0] * b[0] - a[1] * b[1], a[0] * b[1] + a[1] * b[0])
UNITS32 = [r for r in {red32(x, y) for x in range(8) for y in range(8)} if (r[0] + r[1]) % 2 == 1]
SQ32 = {red32(*gmul(w, w)) for w in UNITS32}
def _build2():
    def coset(u): return min(red32(*gmul(u, s)) for s in SQ32)
    gens = []; span = {coset((1, 0)): 0}
    for u in sorted(UNITS32):
        c = coset(u)
        if c in span: continue
        gens.append(u); new = {}
        for cc, vec in span.items(): new[coset(gmul(cc, u))] = vec | (1 << (len(gens) - 1))
        span.update(new)
    return coset, span, gens
COSET2, SPAN2, GENS2 = _build2()
assert len(SPAN2) == 8

def cls2(x, y, prec):
    v = 0
    while True:
        if x % (2 ** prec) == 0 and y % (2 ** prec) == 0: return None
        if (x - y) % 2 == 0:
            x, y = (x + y) // 2, (y - x) // 2; v += 1; prec -= 1
            if prec < 3: return None
        else: break
    if prec < 3: return None
    return (v % 2) | (SPAN2[COSET2(red32(x, y))] << 1)
def cls_split(z, l, prec):
    if z % (l ** prec) == 0: return None
    v = v_l(z, l)
    if v + 1 > prec: return None
    return (v % 2) | (leg(z // l ** v, l) << 1)
def cls_inert(x, y, l, prec):
    M = l ** prec
    if x % M == 0 and y % M == 0: return None
    v = min(v_l(x, l) if x % M else 10**9, v_l(y, l) if y % M else 10**9)
    if v + 1 > prec: return None
    ux, uy = x // l ** v, y // l ** v
    return (v % 2) | (leg(ux * ux + uy * uy, l) << 1)
def elt_class(x, y, l, r=None, prec=40):
    if l == 2: return cls2(x, y, prec)
    if l % 4 == 1:
        M = l ** prec
        return cls_split((x + r * y) % M, l, prec) | (cls_split((x - r * y) % M, l, prec) << 2)
    return cls_inert(x, y, l, prec)
def width(l): return 4 if (l == 2 or l % 4 == 1) else 2

def local_image(AB, l, r, depth=7):
    w = width(l); full = list(range(1 << w)); out = set()
    def classes(x, k, chart):
        res = []
        for (A, B) in AB:
            u, v = (x, 1) if chart == 0 else (1, x)
            X, Y = A * u, B * v
            if l == 2: res.append(cls2(X, Y, k))
            elif l % 4 == 1:
                M = l ** k
                c1 = cls_split((X + r * Y) % M, l, k); c2 = cls_split((X - r * Y) % M, l, k)
                res.append(None if (c1 is None or c2 is None) else (c1 | (c2 << 2)))
            else: res.append(cls_inert(X, Y, l, k))
        return res
    def rec(x, k, chart, dep):
        res = classes(x, k, chart)
        if all(c is not None for c in res) or dep >= depth:
            for combo in itertools.product(*[[c] if c is not None else full for c in res]): out.add(combo)
            return
        for j in range(l): rec(x + j * l ** k, k + 1, chart, dep + 1)
    k0 = 6 if l == 2 else 1
    for x in range(l ** k0): rec(x, k0, 0, 0)
    for x in range(0, l ** k0, l): rec(x, k0, 1, 0)
    return out

def gauss_prime(l):
    for x in range(1, int(math.isqrt(l)) + 1):
        y2 = l - x * x; y = math.isqrt(y2)
        if y * y == y2: return (x, y)
def basis(S):
    B = [('i', (0, 1), {}), ('1+i', (1, 1), {2: 1})]
    for l in S:
        if l == 2: continue
        if l % 4 == 1:
            x, y = gauss_prime(l); B.append((f'pi{l}', (x, y), {l: 1})); B.append((f'pibar{l}', (x, -y), {l: 1}))
        else: B.append((f'q{l}', (l, 0), {}))
    return B

def run(a, b, depth=7):
    Qs, S, sel = selrun(a, b)
    e, f = a + b, a - b; g = math.gcd(e, f)
    AB = [(b, a), (a, b), (f // g, e // g), (e // g, f // g)]
    Sx = sorted(set(S) | {int(q) for q in pari.factor(2 * a * b * e * f)[0]})
    Bs = basis(Sx); nb = len(Bs)
    rmap = {l: (int(pari(f'truncate(sqrt(-1+O({l}^40)))')) if l % 4 == 1 else None) for l in Sx}
    imgs = {l: local_image(AB, l, rmap[l], depth) for l in Sx}
    bcode = {l: [elt_class(x, y, l, rmap[l]) for (_, (x, y), _) in Bs] for l in Sx}
    split_pairs = [(k, k + 1) for k, (nm, _, _) in enumerate(Bs) if nm.startswith('pi') and not nm.startswith('pibar')]
    def cands(dj):   # exponent masks with N(gamma) = dj mod Q*^2
        out = []
        for mask in range(1 << nb):
            if ((mask >> 1) & 1) != (dj % 2 == 0): continue
            ok = True
            for (k1, k2) in split_pairs:
                l = int(Bs[k1][0][2:])
                if (((mask >> k1) & 1) ^ ((mask >> k2) & 1)) != (dj % l == 0): ok = False; break
            if ok: out.append(mask)
        return out
    def loccode(mask, l):
        c = 0
        for k in range(nb):
            if (mask >> k) & 1: c ^= bcode[l][k]
        return c
    results = []; cache = {}
    for delta in sel:
        C = [cands(dj) for dj in delta]
        codes = [{l: np.array([loccode(m, l) for m in Cj], dtype=np.int64) for l in Sx} for Cj in C]
        allowed = {}
        for l in Sx:
            w = width(l); tab = np.zeros(1 << (4 * w), dtype=bool)
            for t4 in imgs[l]: tab[t4[0] | (t4[1] << w) | (t4[2] << 2 * w) | (t4[3] << 3 * w)] = True
            allowed[l] = tab
        ok12 = np.ones((len(C[0]), len(C[1])), dtype=bool)
        for l in Sx:
            w = width(l)
            proj = np.zeros((1 << w, 1 << w), dtype=bool)
            for t4 in imgs[l]: proj[t4[0], t4[1]] = True
            ok12 &= proj[codes[0][l][:, None], codes[1][l][None, :]]
        tuples = []
        for i1, i2 in np.argwhere(ok12):
            ok3 = np.ones(len(C[2]), dtype=bool)
            for l in Sx:
                w = width(l)
                proj3 = np.zeros((1 << w,) * 3, dtype=bool)
                for t4 in imgs[l]: proj3[t4[0], t4[1], t4[2]] = True
                ok3 &= proj3[codes[0][l][i1], codes[1][l][i2], codes[2][l]]
            for i3 in np.nonzero(ok3)[0]:
                ok4 = np.ones(len(C[3]), dtype=bool)
                for l in Sx:
                    w = width(l)
                    code = codes[0][l][i1] | (codes[1][l][i2] << w) | (codes[2][l][i3] << 2 * w) | (codes[3][l] << 3 * w)
                    ok4 &= allowed[l][code]
                for i4 in np.nonzero(ok4)[0]:
                    tuples.append((C[0][i1], C[1][i2], C[2][i3], C[3][i4]))
        for tup in tuples:
            killed = None
            for s in itertools.product([1], [1, -1], [1, -1], [1, -1]):
                G = 0
                for m, sj in zip(tup, s):
                    if sj == 1: G ^= m
                    else:   # conjugate: swap pi/pibar; conj(i) ~ i ; conj(1+i) = (1+i)(-i) ~ (1+i)*i
                        mc = m
                        for (k1, k2) in split_pairs:
                            b1 = (m >> k1) & 1; b2 = (m >> k2) & 1
                            mc &= ~((1 << k1) | (1 << k2)); mc |= (b2 << k1) | (b1 << k2)
                        if (m >> 1) & 1: mc ^= 1
                        G ^= mc
                if (G >> 1) & 1: continue
                if any(((G >> k1) & 1) != ((G >> k2) & 1) for k1, k2 in split_pairs): continue
                d = 1
                if G & 1: d *= 2          # i ~ 2 in K*/K*^2
                for k, (nm, xy, _) in enumerate(Bs):
                    if (G >> k) & 1:
                        if nm.startswith('pi') and not nm.startswith('pibar'): d *= int(nm[2:])
                        elif nm.startswith('q'): d *= int(nm[1:])
                key = (s, d)
                if key not in cache: cache[key] = kill_sd(a, b, s, d)
                if cache[key] == 'KILL': killed = (s, d); break
            results.append((delta, tup, killed))
    unk = [(dl, tp) for dl, tp, k in results if not k]
    kdead = [list(dl) for dl in sel if all(k for d2, tp, k in results if d2 == dl)]
    return dict(p=f'{a}/{b}', nsel=len(sel), ntuples=len(results), excluded=(len(unk) == 0), kdead=kdead,
                unkilled=[[list(dl), [bin(x) for x in tp]] for dl, tp in unk[:6]])

def kill_sd(a, b, s, d):
    L, c = setup(a, b, s)
    coeffs, scale = curveQ(c, d)
    r1 = pari.ellrank(pari.ellinit(coeffs)); r2 = pari.ellrank(pari.ellinit(curveQ(c, -d)[0]))
    if int(r1[1]) != 0 or int(r2[1]) != 0: return 'RANK'
    EK = pari.ellinit(coeffs, K)
    T = pari.elltors(EK); gens = list(T[2]); ords = [int(o) for o in T[1]]
    for co in itertools.product(*[range(o) for o in ords]):
        P = pari('[0]')
        for gg, cc in zip(gens, co): P = pari.elladd(EK, P, pari.ellmul(EK, gg, cc))
        if P == pari('[0]'): continue
        mu = pari.subst(pari.lift(P[0]), 'y', 'I') / pari(f'{scale.numerator}/{scale.denominator}')
        den = a * mu - b
        if den == 0: continue              # t = infinity
        t = pari('I') * (a - s[1] * b * mu) / den
        if pari.imag(t) != 0: continue
        if pari.real(t) in (0, 1, -1): continue
        return 'BAD'
    return 'KILL'

